import json

SMALL, LARGE = "small-model", "large-model"   # 替换为实际模型名

def pick_model(task: str, prompt: str) -> str:
    if task in {"classify", "extract", "translate"} and len(prompt) < 4000:
        return SMALL
    if task in {"code", "plan", "math"}:
        return LARGE
    return SMALL

def valid(output: str) -> bool:
    try:
        json.loads(output)          # 要求结构化输出
        return True
    except ValueError:
        return False

def run(task: str, prompt: str, call_llm) -> str:
    model = pick_model(task, prompt)
    out = call_llm(model, prompt)
    if model == SMALL and not valid(out):
        out = call_llm(LARGE, prompt)   # 级联：小模型不达标就升级
    return out
# call_llm(model, prompt) 由你接入具体 SDK；记录每次的模型、token 与是否升级

import re
from pydantic import BaseModel, Field, ValidationError

class RefundDecision(BaseModel):
    approve: bool
    amount_cents: int = Field(ge=0, le=50_000)   # 金额上限硬约束
    reason: str = Field(max_length=300)

ALLOWED_TOOLS = {"lookup_order", "issue_refund"}
NEEDS_HUMAN = {"issue_refund"}
PII = re.compile(r"\b\d{16}\b")                   # 粗略的卡号模式

def check_output(raw_json: str) -> RefundDecision | None:
    try:
        d = RefundDecision.model_validate_json(raw_json)
    except ValidationError:
        return None                    # 结构不合格：重试或拒绝
    if PII.search(d.reason):
        return None                    # 输出含疑似卡号：拦截
    return d

def check_tool(name: str) -> str:
    if name not in ALLOWED_TOOLS:
        return "deny"
    return "ask_human" if name in NEEDS_HUMAN else "allow"

import json

RISK = {
    "read_file": "low",
    "search": "low",
    "write_file": "medium",
    "send_email": "high",
    "delete_records": "high",
}

def approve(tool: str, args: dict) -> dict | None:
    """返回（可能被修改的）参数；拒绝返回 None"""
    print(f"\n[待审批] {tool}\n{json.dumps(args, ensure_ascii=False, indent=2)}")
    choice = input("批准 y / 拒绝 n / 修改 e: ").strip().lower()
    if choice == "y":
        return args
    if choice == "e":
        return json.loads(input("输入修改后的 JSON 参数: "))
    return None

def execute(tool: str, args: dict, tools: dict):
    level = RISK.get(tool, "high")          # 未登记的工具按高风险处理
    if level != "low":
        args = approve(tool, args)
        if args is None:
            return {"status": "rejected", "tool": tool}   # 反馈给智能体
    return tools[tool](**args)

