const express = require("express");
const crypto = require("crypto");
const app = express();

app.use((req, res, next) => {
  // 每个响应生成新的随机 nonce
  res.locals.nonce = crypto.randomBytes(16).toString("base64");
  res.setHeader("Content-Security-Policy", [
    `script-src 'nonce-${res.locals.nonce}' 'strict-dynamic'`,
    "object-src 'none'",
    "base-uri 'none'",
    "frame-ancestors 'none'",
  ].join("; "));
  next();
});

app.get("/", (req, res) => {
  // 只有带正确 nonce 的脚本能执行，注入的 <script> 会被拦截
  res.send(`<!doctype html>
<script nonce="${res.locals.nonce}" src="/app.js"></script>
<script nonce="${res.locals.nonce}">console.log("ok")</script>`);
});

app.listen(3000);

server {
    listen 443 ssl;
    server_name example.com;

    # always：错误页（4xx/5xx）也带上这些头
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
    add_header Content-Security-Policy "frame-ancestors 'none'; object-src 'none'; base-uri 'none'" always;
    add_header X-Frame-Options "DENY" always;
    add_header Cross-Origin-Opener-Policy "same-origin" always;

    # 注意：location 块里若再写 add_header，
    # 不会继承这里的配置，需要重复声明
    location / {
        proxy_pass http://app:3000;
    }
}

